/* Initialization only: reject stale calibration or a different scene mask. */
static inline int fptz_front_safe_identity(const uint8_t *scene_bits) {
    return scene_bits &&
           strcmp(FPTZ_CALIBRATION_SHA256,FPTZ_FRONT_SAFE_CALIBRATION_SHA256)==0 &&
           fptz_crc32(scene_bits,FPTZ_SCENE_MASK_BYTES)==FPTZ_FRONT_SAFE_MASK_CRC32;
}
static inline int fptz_front_safe_contains(int32_t pan_mdeg,int32_t tilt_mdeg,
                                         uint32_t hfov_mdeg) {
    if(pan_mdeg < -90000 || pan_mdeg > 90000 ||
       tilt_mdeg < -90000 || tilt_mdeg > 90000 ||
       pan_mdeg % FPTZ_FRONT_SAFE_GRID_MDEG ||
       tilt_mdeg % FPTZ_FRONT_SAFE_GRID_MDEG) return 0;
    const int32_t pan=pan_mdeg/FPTZ_FRONT_SAFE_GRID_MDEG;
    const uint32_t row=(uint32_t)(tilt_mdeg/FPTZ_FRONT_SAFE_GRID_MDEG+900);
    for(uint32_t p=0;p<FPTZ_FRONT_SAFE_PRESETS;++p) {
        if(fptz_front_safe_hfov[p]!=hfov_mdeg)continue;
        const uint32_t first=fptz_front_safe_offsets[p][row];
        const uint32_t last=fptz_front_safe_offsets[p][row+1u];
        for(uint32_t i=first;i<last;++i)
            if(pan>=fptz_front_safe_intervals[i].low &&
               pan<=fptz_front_safe_intervals[i].high) return 1;
        return 0;
    }
    return 0;
}
